steps.script:
window.__lmAdmin = {
  page: () => document.querySelector('#LibraryMaintenanceConfigPage:not(.hide)'),
  imports: () => performance.getEntriesByType('resource').filter(e => e.name.indexOf('/LibraryMaintenance/AdminScript') >= 0).length,
  stubs: () => performance.getEntriesByType('resource').filter(e => /configurationpage\?name=LibraryMaintenanceJs/.test(e.name)).length,
  loads: () => performance.getEntriesByType('resource').filter(e => e.name.indexOf('/LibraryMaintenance/Admin/Diagnostics') >= 0).length,
  selected: () => { const p = __lmAdmin.page(); return p ? [...p.querySelectorAll('[role="tab"][aria-selected="true"]')].map(t => t.textContent) : null; },
  rendered: () => { const p = __lmAdmin.page(); return !!p && p.querySelectorAll('[role="tab"]').length === 3 && /^(Index: |The index hasn't been built)/.test((p.querySelector('#LibraryMaintenanceDuplicatesStatus') || {}).textContent || '') && !p.querySelector('#LibraryMaintenanceScriptNote'); },
  history: history.length
};
return { imports: __lmAdmin.imports(), stubs: __lmAdmin.stubs(), page: !!document.querySelector('#LibraryMaintenanceConfigPage') };

window.__lmAdmin = window.__lmAdmin || {
  page: () => document.querySelector('#LibraryMaintenanceConfigPage:not(.hide)'),
  imports: () => performance.getEntriesByType('resource').filter(e => e.name.indexOf('/LibraryMaintenance/AdminScript') >= 0).length,
  selected: () => { const p = __lmAdmin.page(); return p ? [...p.querySelectorAll('[role="tab"][aria-selected="true"]')].map(t => t.textContent) : null; },
  rendered: () => { const p = __lmAdmin.page(); return !!p && p.querySelectorAll('[role="tab"]').length === 3 && /^(Index: |The index hasn't been built)/.test((p.querySelector('#LibraryMaintenanceDuplicatesStatus') || {}).textContent || '') && !p.querySelector('#LibraryMaintenanceScriptNote'); }
};
return true;
